package com.ekzellence.watch;
import android.net.*;
import android.database.Cursor;
import android.content.ContentValues;
import java.net.*;
import java.io.*;
import java.security.MessageDigest;
import org.json.JSONObject;
/** Durable SQLite upload queue; whole-segment retries, checksum receipts, Wi-Fi or mobile data. */
final class CloudBackup {
 static String digest(android.content.Context s,Uri uri)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=open(s,uri)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder out=new StringBuilder();for(byte b:d.digest())out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}
 static InputStream open(android.content.Context s,Uri u)throws Exception{InputStream in=u.getScheme().equals("file")?new FileInputStream(u.getPath()):s.getContentResolver().openInputStream(u);if(in==null)throw new IOException("Local recording unavailable");return in;}
 private static final java.util.concurrent.atomic.AtomicBoolean active=new java.util.concurrent.atomic.AtomicBoolean();
 static void run(WatchService s){run(s,s.store,s.security,message->s.status("cloud",message),()->s.shuttingDown);}
 static void run(android.content.Context s,Store store,Security security,java.util.function.Consumer<String> status,java.util.function.BooleanSupplier stopped){if(!active.compareAndSet(false,true))return;try{transfer(s,store,security,status,stopped);}finally{active.set(false);}}
 static void transfer(android.content.Context s,Store store,Security security,java.util.function.Consumer<String> status,java.util.function.BooleanSupplier stopped){if(!store.prefs.getBoolean("cloudEnabled",false))return;ConnectivityManager cm=s.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm.getNetworkCapabilities(cm.getActiveNetwork());if(caps==null||!caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)||!caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)){status.accept("Offline — recordings queued on tablet");return;}String root=store.prefs.getString("cloudUrl","");if(root.isEmpty())return;
 long budget=System.currentTimeMillis()+20000;
 try(Cursor c=store.getReadableDatabase().rawQuery("SELECT id,camera,uri,start,end,size FROM recordings WHERE cloud=0 AND retryAfter<=? ORDER BY start LIMIT 64",new String[]{""+System.currentTimeMillis()})){
 while(!stopped.getAsBoolean()&&c.moveToNext()&&System.currentTimeMillis()<budget){long id=c.getLong(0);HttpURLConnection h=null;try{String token=security.decrypt(store.prefs.getString("cloudToken",""));String key=c.getString(1)+"/"+c.getLong(3)+".mp4";Uri uri=Uri.parse(c.getString(2));String hash=digest(s,uri);h=(HttpURLConnection)new URL(root+"/recordings/"+key).openConnection();h.setInstanceFollowRedirects(false);h.setConnectTimeout(10000);h.setReadTimeout(45000);h.setRequestMethod("PUT");h.setDoOutput(true);h.setRequestProperty("Authorization","Bearer "+token);h.setRequestProperty("Content-Type","video/mp4");h.setRequestProperty("X-Recording-End",""+c.getLong(4));h.setRequestProperty("X-Recording-SHA256",hash);h.setRequestProperty("X-Camera-Name",java.net.URLEncoder.encode(store.cameraName(c.getString(1)),"UTF-8"));h.setFixedLengthStreamingMode(c.getLong(5));
 try(InputStream in=open(s,uri);OutputStream out=h.getOutputStream()){NativeDownload.copy(in,out);}if(h.getResponseCode()!=200&&h.getResponseCode()!=201)throw new IOException("Cloud refused recording: "+h.getResponseCode());byte[] receipt;try(InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[1024];int n;while((n=in.read(buf))!=-1){if(out.size()+n>8192)throw new IOException("Invalid cloud receipt");out.write(buf,0,n);}receipt=out.toByteArray();}JSONObject confirmation=new JSONObject(new String(receipt,"UTF-8"));if(!hash.equals(confirmation.optString("sha256"))||confirmation.optLong("size",-1)!=c.getLong(5)||!key.equals(confirmation.optString("key")))throw new IOException("Cloud checksum receipt mismatch");
 ContentValues done=new ContentValues();done.put("cloud",1);done.put("lastError","");done.put("retryAfter",0);store.getWritableDatabase().update("recordings",done,"id=?",new String[]{""+id});if(store.prefs.getBoolean("cloudPrimary",false))store.removeVerifiedLocal(id,uri);status.accept("Upload verified · "+new java.text.SimpleDateFormat("HH:mm:ss",java.util.Locale.ROOT).format(new java.util.Date()));
 }catch(Exception e){store.getWritableDatabase().execSQL("UPDATE recordings SET attempts=attempts+1,retryAfter=?,lastError=? WHERE id=?",new Object[]{System.currentTimeMillis()+15000,e.getClass().getSimpleName(),id});status.accept("Upload pending — retrying automatically; local copy retained");}finally{if(h!=null)h.disconnect();}
 }}catch(Exception e){status.accept("Upload queue paused — check storage and connection");}}
}
